CREATE TABLE "admin_oauth_transactions" (
  "state" TEXT PRIMARY KEY NOT NULL, "client_id" TEXT NOT NULL, "redirect_uri" TEXT NOT NULL, "code_verifier" TEXT NOT NULL, "expires_at" TEXT NOT NULL, "created_at" TEXT NOT NULL
);

CREATE TABLE "legacy_import_snapshots" (
  "id" TEXT PRIMARY KEY NOT NULL, "created_at" TEXT NOT NULL, "manifest_sha256" TEXT NOT NULL UNIQUE, "stream_count" BIGINT NOT NULL CHECK ("stream_count" >= 0)
);

CREATE TABLE "legacy_import_streams" (
  "snapshot_id" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_name" TEXT NOT NULL, "destination_prefix" TEXT NOT NULL, "record_count" BIGINT NOT NULL CHECK ("record_count" >= 0), "byte_count" BIGINT NOT NULL CHECK ("byte_count" >= 0), "sha256" TEXT NOT NULL, PRIMARY KEY ("snapshot_id", "source_type", "source_name")
);

CREATE TABLE "assistant_pending_actions" (
  "id" TEXT PRIMARY KEY NOT NULL, "principal_id" TEXT NOT NULL, "domain" TEXT NOT NULL, "command" TEXT NOT NULL, "input_json" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" TEXT NOT NULL, "expires_at" TEXT NOT NULL, "resolved_at" TEXT, "result_json" TEXT, CHECK ("status" IN ('pending', 'executing', 'completed', 'failed', 'cancelled', 'expired'))
);

CREATE TABLE "auto_light_quote_requests" (
  "id" TEXT PRIMARY KEY NOT NULL, "agency_id" BIGINT NOT NULL, "created_by_principal_id" TEXT NOT NULL, "plate" TEXT NOT NULL, "vehicle_source" TEXT NOT NULL, "vehicle_snapshot" TEXT NOT NULL, "applicant_snapshot" TEXT NOT NULL, "coverage_preferences" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, CHECK ("vehicle_source" IN ('equidad', 'sura')), CHECK ("status" IN ('pending', 'in_progress', 'successful', 'partial', 'failed'))
);

CREATE TABLE "auto_light_quote_offers" (
  "id" TEXT PRIMARY KEY NOT NULL, "quote_request_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "operation_id" TEXT NOT NULL, "attempt_number" BIGINT NOT NULL, "status" TEXT NOT NULL, "started_at" TEXT, "completed_at" TEXT, "http_status" BIGINT, "provider_reference" TEXT, "normalized_result" TEXT, "sanitized_response" TEXT, "error_code" TEXT, "error_message" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, credential_owner_principal_id TEXT, CONSTRAINT "auto_light_quote_offers_request_operation_attempt_unique"
    UNIQUE ("quote_request_id", "operation_id", "attempt_number"), CHECK ("attempt_number" > 0), CHECK ("status" IN ('pending', 'in_progress', 'successful', 'failed'))
);

CREATE TABLE "personal_integration_connections" (
  "id" TEXT PRIMARY KEY NOT NULL, "principal_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "nango_connection_id" TEXT NOT NULL, "nango_integration_id" TEXT NOT NULL, "status" TEXT NOT NULL, "external_account_label" TEXT, "external_account_id" TEXT, "scopes" TEXT NOT NULL DEFAULT '[]', "last_validated_at" TEXT, "disconnected_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, CHECK ("provider" IN ('google_drive', 'gmail', 'google_calendar', 'outlook', 'onedrive_personal', 'onedrive_business')), CHECK ("status" IN ('pending', 'connected', 'reconnect_required', 'disconnected', 'failed'))
);

CREATE TABLE "personal_integration_audit_events" (
  "id" TEXT PRIMARY KEY NOT NULL, "connection_id" TEXT NOT NULL, "principal_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "event_type" TEXT NOT NULL, "outcome" TEXT NOT NULL, "error_code" TEXT, "created_at" TEXT NOT NULL);

CREATE TABLE flows (id TEXT PRIMARY KEY, definition TEXT NOT NULL);

CREATE TABLE flow_versions (id TEXT PRIMARY KEY, flow_id TEXT NOT NULL, definition TEXT NOT NULL, created_at TEXT NOT NULL);

CREATE TABLE flow_variables (flow_id TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, secret BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(flow_id, key));

CREATE TABLE flow_runs (id TEXT PRIMARY KEY, flow_id TEXT NOT NULL, version_id TEXT, mode TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, summary TEXT NOT NULL);

CREATE TABLE folders (path TEXT PRIMARY KEY);

CREATE TABLE "user_navigation_preferences" (
  "principal_id" TEXT PRIMARY KEY NOT NULL, "layout" TEXT NOT NULL, "updated_at" TEXT NOT NULL);

CREATE TABLE crm_objects (
 tenant_id TEXT NOT NULL, name TEXT NOT NULL, label TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', config TEXT NOT NULL CHECK(savia_json_valid(config)), created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), version BIGINT NOT NULL DEFAULT 1, PRIMARY KEY (tenant_id, name)
);

CREATE TABLE crm_records (
 id TEXT NOT NULL, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, data TEXT NOT NULL CHECK(savia_json_valid(data)), created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), version BIGINT NOT NULL DEFAULT 1, deleted_at TEXT, created_by TEXT, PRIMARY KEY (tenant_id, id));

CREATE TABLE crm_views (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, name TEXT NOT NULL, config TEXT NOT NULL CHECK(savia_json_valid(config))
);

CREATE TABLE crm_integrations (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, document TEXT NOT NULL CHECK(savia_json_valid(document)), created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
, connection TEXT NOT NULL DEFAULT '{}', encrypted_secret TEXT, owner_principal_id TEXT NOT NULL DEFAULT '');

CREATE TABLE crm_audit (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, action TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE crm_unique_values (tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, field_name TEXT NOT NULL, value TEXT NOT NULL, record_id TEXT NOT NULL, PRIMARY KEY(tenant_id, object_name, field_name, value));

CREATE TABLE crm_write_guards(id TEXT PRIMARY KEY, valid BIGINT NOT NULL CHECK(valid=1));

CREATE TABLE crm_requests(tenant_id TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(tenant_id, request_key));

CREATE TABLE crm_schema_versions(tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, version BIGINT NOT NULL, definition TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(tenant_id, object_name, version));

CREATE TABLE crm_schema_data(tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, version BIGINT NOT NULL, record_id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(tenant_id, object_name, version, record_id));

CREATE TABLE crm_integration_runs (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, integration_id TEXT NOT NULL, operation_id TEXT NOT NULL, method TEXT NOT NULL, status TEXT NOT NULL, http_status BIGINT, attempts BIGINT NOT NULL DEFAULT 0, duration_ms BIGINT NOT NULL DEFAULT 0, error TEXT, response TEXT, idempotency_key TEXT, request_hash TEXT, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE crm_notes (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, body TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'note', version BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));

CREATE TABLE crm_files (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size BIGINT NOT NULL, storage_key TEXT NOT NULL UNIQUE, version BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), field_name TEXT NOT NULL DEFAULT '');

CREATE TABLE crm_automations (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, name TEXT NOT NULL, config TEXT NOT NULL CHECK(savia_json_valid(config)), enabled BIGINT NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE crm_automation_runs (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, automation_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, event_key TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL, task_id TEXT, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(tenant_id, automation_id, event_key)
);

CREATE TABLE crm_tasks (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, title TEXT NOT NULL, owner TEXT NOT NULL DEFAULT '', due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', version BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));

CREATE TABLE crm_business_links (
 tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, connection_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('syncing', 'synced', 'uncertain')), external_object_id TEXT, last_synced_at TEXT, PRIMARY KEY(tenant_id, object_name, record_id, connection_id));

CREATE TABLE crm_data_domains (
 id TEXT PRIMARY KEY NOT NULL, label TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE managed_customer_extensions (
  tenant_id TEXT NOT NULL, profile_id BIGINT NOT NULL, data TEXT NOT NULL DEFAULT '{}' CHECK(savia_json_valid(data)), version BIGINT NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, PRIMARY KEY(tenant_id, profile_id));

CREATE TABLE managed_customer_requests (
  tenant_id TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL CHECK(savia_json_valid(response)), PRIMARY KEY(tenant_id, request_key)
);

CREATE TABLE crm_collection_bindings (
 tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, source_id TEXT NOT NULL, resource TEXT NOT NULL, config TEXT NOT NULL CHECK(savia_json_valid(config)), PRIMARY KEY(tenant_id, object_name));

CREATE TABLE crm_collection_requests (
 tenant_id TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending', 'success')), response TEXT CHECK(response IS NULL OR savia_json_valid(response)), PRIMARY KEY(tenant_id, request_key)
);

CREATE TABLE crm_collection_relations (
 tenant_id TEXT NOT NULL, id TEXT NOT NULL, source_object TEXT NOT NULL, target_object TEXT NOT NULL, source_label TEXT NOT NULL, target_label TEXT NOT NULL, cardinality TEXT NOT NULL CHECK(cardinality IN ('one-to-one', 'one-to-many', 'many-to-many')), source_field TEXT NOT NULL DEFAULT 'id', target_field TEXT NOT NULL DEFAULT 'id', source_display_field TEXT, target_display_field TEXT, storage TEXT NOT NULL DEFAULT 'local' CHECK(storage IN ('local', 'fields')), version BIGINT NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id, id));

CREATE TABLE crm_record_links (
 tenant_id TEXT NOT NULL, relation_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, PRIMARY KEY(tenant_id, relation_id, source_id, target_id));

CREATE TABLE crm_native_relation_overrides(tenant_id TEXT NOT NULL, id TEXT NOT NULL, config TEXT NOT NULL CHECK(savia_json_valid(config)), version BIGINT NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id, id));

CREATE TABLE crm_file_drafts (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, field_name TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size BIGINT NOT NULL, storage_key TEXT NOT NULL UNIQUE, version BIGINT NOT NULL DEFAULT 1, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE tenants (
 id BIGINT PRIMARY KEY NOT NULL, id_slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, is_active BIGINT NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL
, kind TEXT NOT NULL DEFAULT 'commercial' CHECK(kind IN ('commercial', 'platform')));

CREATE TABLE identity_tenant_membership (
 id TEXT PRIMARY KEY NOT NULL, principal_id TEXT NOT NULL UNIQUE, tenant_id BIGINT NOT NULL, role TEXT NOT NULL CHECK (role IN ('agency_admin', 'tenant_admin', 'operator', 'viewer')), is_active BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);

CREATE TABLE customer_crm_sync_records (
 principal_id TEXT NOT NULL, agency_id BIGINT NOT NULL, customer_profile_id BIGINT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('hubspot', 'salesforce', 'zoho', 'pipedrive')), object_kind TEXT NOT NULL CHECK(object_kind IN ('contact', 'company')), external_object_id TEXT NOT NULL, last_synced_at TEXT, last_failure_code TEXT, last_failure_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(principal_id, agency_id, customer_profile_id, provider, object_kind)
);

CREATE TABLE "agency_crm_connections" (
 id TEXT PRIMARY KEY NOT NULL, agency_id BIGINT NOT NULL, created_by_principal_id TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('hubspot', 'salesforce', 'zoho', 'pipedrive')), nango_connection_id TEXT NOT NULL, nango_integration_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending', 'connected', 'reconnect_required', 'disconnected', 'failed')), external_account_label TEXT, scopes TEXT NOT NULL DEFAULT '[]', last_validated_at TEXT, disconnected_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, external_account_id TEXT
);

CREATE TABLE agency_crm_connection_audit_events (
 id TEXT PRIMARY KEY NOT NULL, connection_id TEXT NOT NULL, agency_id BIGINT NOT NULL, principal_id TEXT NOT NULL, provider TEXT NOT NULL, event_type TEXT NOT NULL, outcome TEXT NOT NULL, error_code TEXT, created_at TEXT NOT NULL
);

CREATE TABLE "user_provider_credentials" (
  "id" TEXT PRIMARY KEY NOT NULL, "owner_principal_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "schema_version" BIGINT NOT NULL, "credential_ciphertext" TEXT NOT NULL, "credential_iv" TEXT NOT NULL, "last_validation_status" TEXT, "last_validation_error_code" TEXT, "last_validated_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "created_by_principal_id" TEXT NOT NULL, "updated_by_principal_id" TEXT NOT NULL, CHECK ("schema_version" > 0), CHECK ("last_validation_status" IN ('valid', 'invalid') OR "last_validation_status" IS NULL)
);

CREATE TABLE "user_provider_credential_audit_events" (
  "id" TEXT PRIMARY KEY NOT NULL, "owner_principal_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "actor_principal_id" TEXT NOT NULL, "event_type" TEXT NOT NULL, "outcome" TEXT NOT NULL, "error_code" TEXT, "created_at" TEXT NOT NULL, CHECK ("event_type" IN ('created', 'replaced', 'revealed', 'tested', 'deleted'))
);

CREATE TABLE request_page_runs (
  id TEXT PRIMARY KEY NOT NULL, principal_id TEXT NOT NULL, domain_id TEXT NOT NULL, page_name TEXT NOT NULL, action_id TEXT NOT NULL, action_label TEXT NOT NULL, mode TEXT NOT NULL CHECK (mode IN ('mock', 'live')), status TEXT NOT NULL CHECK (status IN ('running', 'complete', 'failed')), form_values TEXT NOT NULL, result TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);

CREATE TABLE "user_appearance_preferences" (
  "principal_id" TEXT PRIMARY KEY NOT NULL, "settings" TEXT NOT NULL, "updated_at" TEXT NOT NULL);

CREATE TABLE crm_studio_settings (
  tenant_id TEXT PRIMARY KEY, menu_layout TEXT CHECK(menu_layout IS NULL OR savia_json_valid(menu_layout)), updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE crm_sync_jobs (
 id TEXT PRIMARY KEY, rule_id TEXT NOT NULL, customer_id BIGINT NOT NULL, revision BIGINT NOT NULL DEFAULT 1, synced_revision BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'processing', 'synced', 'failed', 'blocked')), attempts BIGINT NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), lease_token TEXT, lease_started_at TEXT, last_error TEXT, external_url TEXT, updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(rule_id, customer_id)
);

CREATE TABLE crm_sync_mappings (
 rule_id TEXT NOT NULL, customer_id BIGINT NOT NULL, object_kind TEXT NOT NULL CHECK(object_kind IN ('contact', 'company')), external_object_id TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(rule_id, customer_id, object_kind)
);

CREATE TABLE crm_solution_installations (
 tenant_id TEXT NOT NULL, id TEXT NOT NULL, version TEXT NOT NULL, enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)), manifest TEXT NOT NULL CHECK(savia_json_valid(manifest)), installed_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(tenant_id, id)
);

CREATE TABLE crm_solution_objects (
 tenant_id TEXT NOT NULL, solution_id TEXT NOT NULL, object_name TEXT NOT NULL, definition TEXT NOT NULL CHECK(savia_json_valid(definition)), PRIMARY KEY(tenant_id, object_name));

CREATE TABLE crm_sync_rules (
 id TEXT PRIMARY KEY, principal_id TEXT NOT NULL, tenant_id BIGINT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('hubspot', 'salesforce', 'zoho', 'pipedrive')), connection_id TEXT NOT NULL, external_account_id TEXT NOT NULL, account_label TEXT NOT NULL, enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)), created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(principal_id, tenant_id, provider, connection_id, external_account_id)
);

CREATE TABLE "assistant_openrouter_settings" (
  "id" TEXT PRIMARY KEY NOT NULL, "scope" TEXT NOT NULL, "agency_id" BIGINT, "api_key_ciphertext" TEXT, "api_key_iv" TEXT, "model" TEXT, "updated_at" TEXT NOT NULL, "updated_by" TEXT NOT NULL, CHECK ("scope" IN ('global', 'agency')), CHECK (
    ("scope" = 'global' AND "id" = 'global' AND "agency_id" IS NULL) OR
    ("scope" = 'agency' AND "id" = 'agency:' || "agency_id" AND "agency_id" IS NOT NULL)
  ), CHECK (("api_key_ciphertext" IS NULL) = ("api_key_iv" IS NULL))
);

CREATE TABLE "assistant_active_agencies" (
  "principal_id" TEXT PRIMARY KEY NOT NULL, "agency_id" BIGINT NOT NULL, "updated_at" TEXT NOT NULL);

CREATE TABLE "assistant_virtual_employees" (
  "id" TEXT PRIMARY KEY NOT NULL, "agency_id" BIGINT, "name" TEXT NOT NULL, "handle" TEXT NOT NULL, "position" TEXT, "avatar" TEXT, "greeting" TEXT, "system_prompt" TEXT NOT NULL, "allowed_collections" TEXT NOT NULL DEFAULT '["*"]', "model" TEXT, "status" TEXT NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'inactive')), "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "created_by" TEXT);

CREATE TABLE "assistant_virtual_employee_files" (
  "id" TEXT PRIMARY KEY NOT NULL, "employee_id" TEXT NOT NULL, "name" TEXT NOT NULL, "content_type" TEXT NOT NULL, "size_bytes" BIGINT NOT NULL, "r2_key" TEXT NOT NULL, "rag_status" TEXT NOT NULL DEFAULT 'indexed' CHECK ("rag_status" IN ('pending', 'indexed', 'failed')), "created_at" TEXT NOT NULL);

CREATE TABLE "assistant_virtual_employee_chunks" (
  "id" TEXT PRIMARY KEY NOT NULL, "employee_id" TEXT NOT NULL, "file_id" TEXT NOT NULL, "chunk_index" BIGINT NOT NULL, "text" TEXT NOT NULL, "vector_id" TEXT, "created_at" TEXT NOT NULL);

CREATE TABLE crm_geocoding_settings (
  tenant_id TEXT PRIMARY KEY, encrypted_geoapify_key TEXT, updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE crm_extension_installations (
 tenant_id TEXT NOT NULL, id TEXT NOT NULL, version TEXT NOT NULL, enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)), manifest TEXT NOT NULL CHECK(savia_json_valid(manifest)), installed_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(tenant_id, id)
);

CREATE TABLE tenant_consolidation_sources (
 source_tenant_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, target_tenant_id BIGINT NOT NULL, consolidated_at TEXT NOT NULL
);

CREATE TABLE tenant_consolidation_discards (
 source_tenant_id BIGINT NOT NULL, target_tenant_id BIGINT NOT NULL, table_name TEXT NOT NULL, record_key TEXT NOT NULL, discarded_at TEXT NOT NULL, PRIMARY KEY(source_tenant_id, table_name, record_key)
);

CREATE TABLE tenant_consolidation_agency_bootstraps (
 target_tenant_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_tenant_id BIGINT NOT NULL, temporary_short_name TEXT NOT NULL
);

CREATE TABLE extension_connections (
  tenant_id TEXT NOT NULL, extension_id TEXT NOT NULL, id TEXT NOT NULL, connector_id TEXT NOT NULL, credential_ciphertext TEXT NOT NULL, credential_iv TEXT NOT NULL, created_by_principal_id TEXT NOT NULL, updated_by_principal_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, extension_id, id)
);

CREATE TABLE extension_connection_audit_events (
  id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, extension_id TEXT NOT NULL, connection_id TEXT NOT NULL, actor_principal_id TEXT NOT NULL, event_type TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('success', 'failure')), error_code TEXT, created_at TEXT NOT NULL
);

CREATE TABLE extension_action_runs (
  tenant_id TEXT NOT NULL, run_id TEXT NOT NULL, extension_id TEXT NOT NULL, action_id TEXT NOT NULL, connection_id TEXT NOT NULL, principal_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'succeeded', 'failed', 'expired')), input TEXT NOT NULL CHECK (savia_json_valid(input)), output TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, run_id)
);

CREATE TABLE extension_settings (
  tenant_id TEXT NOT NULL, extension_id TEXT NOT NULL, value TEXT NOT NULL CHECK (savia_json_valid(value)), version BIGINT NOT NULL, created_by_principal_id TEXT NOT NULL, updated_by_principal_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, extension_id)
);

CREATE TABLE crm_collection_versions (
  tenant_id TEXT NOT NULL, collection TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, collection)
);

CREATE TABLE offline_collection_policies (
  tenant_id BIGINT NOT NULL, collection TEXT NOT NULL, is_enabled BIGINT NOT NULL DEFAULT 1, refresh_seconds BIGINT NOT NULL DEFAULT 300, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, collection)
);

CREATE TABLE crm_sync_changes (
 sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY , tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, version BIGINT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, created_by TEXT, UNIQUE(tenant_id, object_name, id)
);

CREATE TABLE crm_sync_receipts (
 tenant_id TEXT NOT NULL, principal_id TEXT NOT NULL, mutation_id TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL, before_state TEXT, effects_applied BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id, principal_id, mutation_id)
);

CREATE TABLE public_forms (
 id TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, tenant_id TEXT NOT NULL, domain_id TEXT NOT NULL, object_name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('record', 'quote')), title TEXT NOT NULL, description TEXT, fields TEXT NOT NULL CHECK(savia_json_valid(fields)), snapshot TEXT NOT NULL CHECK(savia_json_valid(snapshot)), daily_limit BIGINT NOT NULL CHECK(daily_limit BETWEEN 1 AND 1000), return_result BIGINT NOT NULL DEFAULT 0 CHECK(return_result IN (0, 1)), expires_at TEXT, revoked_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);

CREATE TABLE public_form_submissions (
 form_id TEXT NOT NULL, submission_id TEXT NOT NULL, tenant_id TEXT NOT NULL, ip_hash TEXT NOT NULL, day TEXT NOT NULL, fingerprint TEXT NOT NULL, captcha_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved', 'complete', 'failed')), response TEXT CHECK(response IS NULL OR savia_json_valid(response)), created_at TEXT NOT NULL, PRIMARY KEY(form_id, submission_id), UNIQUE(captcha_hash)
);

CREATE TABLE workflows (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, definition TEXT NOT NULL CHECK(savia_json_valid(definition)), revision BIGINT NOT NULL DEFAULT 1, enabled BIGINT NOT NULL DEFAULT 0, published_version TEXT, created_by TEXT NOT NULL, next_run_at BIGINT, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(workspace_id, id)
);

CREATE TABLE workflow_versions (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, workflow_id TEXT NOT NULL, definition TEXT NOT NULL CHECK(savia_json_valid(definition)), owner_id TEXT NOT NULL, revision BIGINT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(workspace_id, id), UNIQUE(workspace_id, workflow_id, revision));

CREATE TABLE workflow_events (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY , workspace_id TEXT NOT NULL, collection TEXT NOT NULL, kind TEXT NOT NULL, before_state TEXT NOT NULL, after_state TEXT NOT NULL, depth BIGINT NOT NULL DEFAULT 0, cause TEXT, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE workflow_executions (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, workflow_id TEXT NOT NULL, version_id TEXT NOT NULL, owner_id TEXT NOT NULL, initiator_id TEXT NOT NULL, event_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued', 'running', 'waiting', 'completed', 'failed', 'blocked', 'cancelled')), node_id TEXT, context TEXT NOT NULL CHECK(savia_json_valid(context)), depth BIGINT NOT NULL DEFAULT 0, wake_at BIGINT NOT NULL DEFAULT 0, lease_token TEXT, lease_until BIGINT NOT NULL DEFAULT 0, attempts BIGINT NOT NULL DEFAULT 0, error TEXT, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(workspace_id, id), UNIQUE(workspace_id, workflow_id, event_key));

CREATE TABLE workflow_jobs (
 workspace_id TEXT NOT NULL, execution_id TEXT NOT NULL, node_id TEXT NOT NULL, sequence BIGINT NOT NULL, type TEXT NOT NULL, input TEXT NOT NULL, output TEXT NOT NULL, attempts BIGINT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(workspace_id, execution_id, node_id));

CREATE TABLE workflow_tasks (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, execution_id TEXT NOT NULL, node_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('task', 'notification')), title TEXT NOT NULL, assignee TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open', 'done')), due_at BIGINT, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(workspace_id, id), UNIQUE(workspace_id, execution_id, node_id));

CREATE TABLE workflow_write_context (
 workspace_id TEXT NOT NULL, record_id TEXT NOT NULL, depth BIGINT NOT NULL, cause TEXT NOT NULL, PRIMARY KEY(workspace_id, record_id)
);

CREATE TABLE access_revisions (scope TEXT PRIMARY KEY, revision BIGINT NOT NULL DEFAULT 0 CHECK(revision>=0));

CREATE TABLE access_roles (
 id TEXT NOT NULL, scope TEXT NOT NULL, name TEXT NOT NULL, label TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)), protected BIGINT NOT NULL DEFAULT 0 CHECK(protected IN (0, 1)), legacy_role TEXT, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(scope, id), UNIQUE(scope, name));

CREATE TABLE access_grants (
 id TEXT PRIMARY KEY, scope TEXT NOT NULL, role_id TEXT NOT NULL, resource TEXT NOT NULL, action TEXT NOT NULL, predicate TEXT NOT NULL CHECK(savia_json_valid(predicate)), fields TEXT NOT NULL CHECK(savia_json_valid(fields)));

CREATE TABLE access_assignments (
 scope TEXT NOT NULL, principal_id TEXT NOT NULL, role_id TEXT NOT NULL, PRIMARY KEY(scope, principal_id, role_id));

CREATE TABLE access_audit (
 id TEXT PRIMARY KEY, scope TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, before_state TEXT, after_state TEXT, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE TABLE "crm_collection_sources" (
  tenant_id TEXT NOT NULL, owner_principal_id TEXT NOT NULL, id TEXT NOT NULL, label TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('jsonapi', 'postgres', 'mysql', 'mssql', 'mongodb')), config TEXT NOT NULL CHECK(savia_json_valid(config)), encrypted_secret TEXT, created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(tenant_id, owner_principal_id, id)
);

CREATE TABLE crm_file_revisions (
 tenant_id TEXT NOT NULL, file_id TEXT NOT NULL, version BIGINT NOT NULL CHECK(version > 0), storage_key TEXT NOT NULL UNIQUE, size BIGINT NOT NULL CHECK(size > 0), created_at TEXT NOT NULL DEFAULT (to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), created_by TEXT, PRIMARY KEY(tenant_id, file_id, version)
);

CREATE TABLE tenant_branding (
 tenant_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, config TEXT NOT NULL CHECK(savia_json_valid(config)), version BIGINT NOT NULL CHECK(version > 0), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);

CREATE TABLE tenant_branding_assets (
 id TEXT PRIMARY KEY, tenant_id BIGINT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('logo', 'cover')), object_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'live' CHECK(state IN ('live', 'uploading', 'deleting')), content_type TEXT NOT NULL CHECK(content_type IN ('image/png', 'image/jpeg', 'image/webp')), size BIGINT NOT NULL CHECK(size > 0 AND size <= 2097152), created_by TEXT NOT NULL, created_at TEXT NOT NULL
);

CREATE TABLE crm_access_deliveries (principal_id TEXT NOT NULL, scope TEXT NOT NULL, revision BIGINT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, PRIMARY KEY(principal_id, scope, revision, object_name, record_id));

CREATE TABLE crm_record_history (
 tenant_id TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, version BIGINT NOT NULL, action TEXT NOT NULL CHECK(action IN ('created', 'updated', 'deleted', 'restored')), created_at TEXT NOT NULL, actor_kind TEXT NOT NULL CHECK(actor_kind IN ('user', 'workflow', 'public-form', 'system')), actor_id TEXT, cause_id TEXT, changes TEXT NOT NULL CHECK(savia_json_valid(changes)), expires_at TEXT NOT NULL, PRIMARY KEY(tenant_id, object_name, record_id, version)
);

CREATE TABLE crm_record_history_context (
 tenant_id TEXT PRIMARY KEY, actor_kind TEXT NOT NULL, actor_id TEXT, cause_id TEXT
);

CREATE TABLE workflow_webhook_endpoints (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL UNIQUE, workflow_id TEXT NOT NULL, secret_hash TEXT NOT NULL, PRIMARY KEY(workspace_id, id), UNIQUE(workspace_id, workflow_id));

CREATE TABLE workflow_webhook_receipts (
 workspace_id TEXT NOT NULL, endpoint_id TEXT NOT NULL, event_key TEXT NOT NULL, payload_hash TEXT NOT NULL, execution_id TEXT NOT NULL, PRIMARY KEY(workspace_id, endpoint_id, event_key));

CREATE TABLE workflow_webhook_admissions (
 endpoint_id TEXT NOT NULL, minute BIGINT NOT NULL, count BIGINT NOT NULL CHECK(count BETWEEN 1 AND 60), PRIMARY KEY(endpoint_id, minute));

CREATE TABLE workflow_webhook_destinations (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, current_revision BIGINT NOT NULL, enabled BIGINT NOT NULL DEFAULT 1, encrypted_secret TEXT, credential_type TEXT NOT NULL, credential_header TEXT, PRIMARY KEY(workspace_id, id)
);

CREATE TABLE workflow_webhook_destination_versions (
 workspace_id TEXT NOT NULL, id TEXT NOT NULL, revision BIGINT NOT NULL, url TEXT NOT NULL, auth_type TEXT NOT NULL, auth_header TEXT, PRIMARY KEY(workspace_id, id, revision));

CREATE TABLE workflow_webhook_deliveries (
 workspace_id TEXT NOT NULL, execution_id TEXT NOT NULL, node_id TEXT NOT NULL, destination_id TEXT NOT NULL, destination_revision BIGINT NOT NULL, payload TEXT NOT NULL, stable_key TEXT NOT NULL, attempt_count BIGINT NOT NULL DEFAULT 0, retry_generation BIGINT NOT NULL DEFAULT 0, generation_attempts BIGINT NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'prepared', PRIMARY KEY(workspace_id, execution_id, node_id));

CREATE TABLE workflow_webhook_attempts (
 workspace_id TEXT NOT NULL, execution_id TEXT NOT NULL, node_id TEXT NOT NULL, sequence BIGINT NOT NULL, lease_token TEXT NOT NULL, started_at BIGINT NOT NULL, finished_at BIGINT, status BIGINT, error TEXT, output TEXT, PRIMARY KEY(workspace_id, execution_id, node_id, sequence));

