CREATE FUNCTION crm_record_links_cardinality_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
-- Serialize link guards with competing links and definition UPDATE row locks.
-- The separate check statement receives a fresh READ COMMITTED snapshot after waiting.
PERFORM 1 FROM crm_collection_relations
 WHERE tenant_id=NEW.tenant_id AND id=NEW.relation_id FOR UPDATE;
IF EXISTS (
 SELECT 1 FROM crm_collection_relations r JOIN crm_record_links e ON e.tenant_id=r.tenant_id AND e.relation_id=r.id
 WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.relation_id
 AND ((r.cardinality='one-to-one' AND e.source_id=NEW.source_id AND e.target_id<>NEW.target_id)
 OR (r.cardinality IN ('one-to-one','one-to-many') AND e.target_id=NEW.target_id AND e.source_id<>NEW.source_id))
 ) THEN RAISE EXCEPTION 'relation_cardinality_conflict'; END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_record_links_cardinality BEFORE INSERT ON crm_record_links FOR EACH ROW EXECUTE FUNCTION crm_record_links_cardinality_fn();

CREATE FUNCTION crm_relation_definition_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF (NEW.source_field<>OLD.source_field OR NEW.target_field<>OLD.target_field OR NEW.storage<>OLD.storage) AND EXISTS(SELECT 1 FROM crm_record_links WHERE tenant_id=OLD.tenant_id AND relation_id=OLD.id) THEN RAISE EXCEPTION 'relation_mapping_has_links'; END IF;
 IF (NEW.cardinality='one-to-one' AND EXISTS(SELECT 1 FROM crm_record_links WHERE tenant_id=OLD.tenant_id AND relation_id=OLD.id GROUP BY source_id HAVING count(*)>1)) OR (NEW.cardinality IN ('one-to-one','one-to-many') AND EXISTS(SELECT 1 FROM crm_record_links WHERE tenant_id=OLD.tenant_id AND relation_id=OLD.id GROUP BY target_id HAVING count(*)>1)) THEN RAISE EXCEPTION 'relation_cardinality_conflict'; END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_relation_definition_update BEFORE UPDATE ON crm_collection_relations FOR EACH ROW EXECUTE FUNCTION crm_relation_definition_update_fn();

CREATE FUNCTION crm_record_links_storage_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
-- Serialize link guards with competing links and definition UPDATE row locks.
-- The separate check statement receives a fresh READ COMMITTED snapshot after waiting.
PERFORM 1 FROM crm_collection_relations
 WHERE tenant_id=NEW.tenant_id AND id=NEW.relation_id FOR UPDATE;
IF EXISTS(SELECT 1 FROM crm_collection_relations WHERE tenant_id=NEW.tenant_id AND id=NEW.relation_id AND storage<>'local') THEN RAISE EXCEPTION 'relation_mapping_has_links'; END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_record_links_storage BEFORE INSERT ON crm_record_links FOR EACH ROW EXECUTE FUNCTION crm_record_links_storage_fn();

CREATE FUNCTION agency_tenant_identity_insert_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.tenant_id IS NOT NULL AND NEW.tenant_id != NEW.id THEN
RAISE EXCEPTION 'Agency profile must use its tenant identity';
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER agency_tenant_identity_insert BEFORE INSERT ON agencies FOR EACH ROW EXECUTE FUNCTION agency_tenant_identity_insert_fn();

CREATE FUNCTION agency_tenant_identity_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.id != OLD.id OR NEW.tenant_id IS NULL OR NEW.tenant_id != NEW.id THEN
RAISE EXCEPTION 'Agency profile must use its tenant identity';
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER agency_tenant_identity_update BEFORE UPDATE OF id,tenant_id ON agencies FOR EACH ROW EXECUTE FUNCTION agency_tenant_identity_update_fn();

CREATE FUNCTION agency_tenant_create_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO tenants(id,id_slug,name,is_active,created_at,updated_at)
 VALUES(NEW.id,NEW.id_slug,NEW.name,NEW.is_active,NEW.created_at,NEW.updated_at)
 ON CONFLICT(id) DO UPDATE SET id_slug=excluded.id_slug,name=excluded.name,is_active=excluded.is_active,updated_at=excluded.updated_at;
 UPDATE agencies SET tenant_id=NEW.id WHERE id=NEW.id;
RETURN NEW;
END $trigger$;
CREATE TRIGGER agency_tenant_create AFTER INSERT ON agencies FOR EACH ROW EXECUTE FUNCTION agency_tenant_create_fn();

CREATE FUNCTION agency_tenant_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.id_slug != OLD.id_slug OR NEW.name != OLD.name OR NEW.is_active != OLD.is_active OR NEW.updated_at != OLD.updated_at THEN
UPDATE tenants SET id_slug=NEW.id_slug,name=NEW.name,is_active=NEW.is_active,updated_at=NEW.updated_at WHERE id=NEW.id;
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER agency_tenant_update AFTER UPDATE OF id_slug,name,is_active,updated_at ON agencies FOR EACH ROW EXECUTE FUNCTION agency_tenant_update_fn();

CREATE FUNCTION tenant_agency_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.id_slug != OLD.id_slug OR NEW.name != OLD.name OR NEW.is_active != OLD.is_active OR NEW.updated_at != OLD.updated_at THEN
UPDATE agencies SET id_slug=NEW.id_slug,name=NEW.name,is_active=NEW.is_active,updated_at=NEW.updated_at WHERE tenant_id=NEW.id;
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER tenant_agency_update AFTER UPDATE OF id_slug,name,is_active,updated_at ON tenants FOR EACH ROW EXECUTE FUNCTION tenant_agency_update_fn();

CREATE FUNCTION crm_sync_customer_naturalperson_insert_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_jobs(id,rule_id,customer_id)
 SELECT r.id || ':' || p.id,r.id,p.id FROM crm_sync_rules r JOIN customer_clientagency p ON p.agency_id=r.tenant_id
 WHERE r.enabled=1 AND p.id=NEW.client_id
 ON CONFLICT(rule_id,customer_id) DO UPDATE SET
 revision=crm_sync_jobs.revision+1,
 status=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.status ELSE 'pending' END,
 attempts=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.attempts ELSE 0 END,
 last_error=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.last_error ELSE NULL END,
 next_attempt_at=to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 updated_at=to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_sync_customer_naturalperson_insert AFTER INSERT ON customer_naturalperson FOR EACH ROW EXECUTE FUNCTION crm_sync_customer_naturalperson_insert_fn();

CREATE FUNCTION crm_sync_customer_naturalperson_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_jobs(id,rule_id,customer_id)
 SELECT r.id || ':' || p.id,r.id,p.id FROM crm_sync_rules r JOIN customer_clientagency p ON p.agency_id=r.tenant_id
 WHERE r.enabled=1 AND p.id=NEW.client_id
 ON CONFLICT(rule_id,customer_id) DO UPDATE SET
 revision=crm_sync_jobs.revision+1,
 status=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.status ELSE 'pending' END,
 attempts=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.attempts ELSE 0 END,
 last_error=CASE WHEN crm_sync_jobs.status='processing' OR (crm_sync_jobs.status='blocked' AND COALESCE(crm_sync_jobs.last_error,'')<>'RULE_PAUSED') THEN crm_sync_jobs.last_error ELSE NULL END,
 next_attempt_at=to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 updated_at=to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_sync_customer_naturalperson_update AFTER UPDATE ON customer_naturalperson FOR EACH ROW EXECUTE FUNCTION crm_sync_customer_naturalperson_update_fn();

CREATE FUNCTION crm_sync_customer_legalperson_insert_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_jobs(id,rule_id,customer_id)
 SELECT r.id || ':' || p.id,r.id,p.id FROM crm_sync_rules r JOIN customer_clientagency p ON p.agency_id=r.tenant_id
 WHERE r.enabled=1 AND p.id=NEW.client_id
 ON CONFLICT(rule_id,customer_id) DO UPDATE SET
