CREATE FUNCTION access_tenant_created_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.id>0 THEN
INSERT INTO access_revisions(scope) VALUES ('tenant:'||NEW.id) ON CONFLICT DO NOTHING;
 INSERT INTO access_roles(id,scope,name,label,protected,legacy_role)
 SELECT 'builtin:tenant:'||NEW.id||':'||r.name,'tenant:'||NEW.id,r.name,r.name,1,r.name
 FROM (SELECT 'tenant_admin' name UNION ALL SELECT 'agency_admin' UNION ALL SELECT 'operator' UNION ALL SELECT 'viewer') r;
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_tenant_created AFTER INSERT ON tenants FOR EACH ROW EXECUTE FUNCTION access_tenant_created_fn();

CREATE FUNCTION access_domain_created_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO access_revisions(scope) VALUES ('domain:'||NEW.id) ON CONFLICT DO NOTHING;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_domain_created AFTER INSERT ON crm_data_domains FOR EACH ROW EXECUTE FUNCTION access_domain_created_fn();

CREATE FUNCTION access_membership_created_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF NEW.tenant_id>0 THEN
INSERT INTO access_assignments(scope,principal_id,role_id)
 VALUES('tenant:'||NEW.tenant_id,NEW.principal_id,'builtin:tenant:'||NEW.tenant_id||':'||NEW.role) ON CONFLICT DO NOTHING;
 UPDATE access_revisions SET revision=revision+1 WHERE scope='tenant:'||NEW.tenant_id;
END IF;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_membership_created AFTER INSERT ON identity_tenant_membership FOR EACH ROW EXECUTE FUNCTION access_membership_created_fn();

CREATE FUNCTION access_membership_changed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
DELETE FROM access_assignments WHERE principal_id=OLD.principal_id AND scope='tenant:'||OLD.tenant_id
 AND (OLD.tenant_id<>NEW.tenant_id OR role_id LIKE 'builtin:%');
 INSERT INTO access_assignments(scope,principal_id,role_id)
 SELECT 'tenant:'||NEW.tenant_id,NEW.principal_id,'builtin:tenant:'||NEW.tenant_id||':'||NEW.role WHERE NEW.tenant_id>0 ON CONFLICT DO NOTHING;
 UPDATE access_revisions SET revision=revision+1 WHERE scope IN ('tenant:'||OLD.tenant_id,'tenant:'||NEW.tenant_id);
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_membership_changed AFTER UPDATE OF tenant_id,role,is_active ON identity_tenant_membership FOR EACH ROW EXECUTE FUNCTION access_membership_changed_fn();

CREATE FUNCTION access_membership_removed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
DELETE FROM access_assignments WHERE principal_id=OLD.principal_id AND scope='tenant:'||OLD.tenant_id;
 UPDATE access_revisions SET revision=revision+1 WHERE scope='tenant:'||OLD.tenant_id;
RETURN OLD;
END $trigger$;
CREATE TRIGGER access_membership_removed AFTER DELETE ON identity_tenant_membership FOR EACH ROW EXECUTE FUNCTION access_membership_removed_fn();

CREATE FUNCTION access_principal_changed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1 WHERE scope IN (SELECT scope FROM access_assignments WHERE principal_id=NEW.id);
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_principal_changed AFTER UPDATE OF is_active ON identity_principal FOR EACH ROW EXECUTE FUNCTION access_principal_changed_fn();

CREATE FUNCTION access_global_role_removed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1;
RETURN OLD;
END $trigger$;
CREATE TRIGGER access_global_role_removed AFTER DELETE ON identity_global_role FOR EACH ROW EXECUTE FUNCTION access_global_role_removed_fn();

CREATE FUNCTION access_global_role_added_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_global_role_added AFTER INSERT ON identity_global_role FOR EACH ROW EXECUTE FUNCTION access_global_role_added_fn();

CREATE FUNCTION access_tenant_state_changed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1 WHERE scope='tenant:'||NEW.id;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_tenant_state_changed AFTER UPDATE OF is_active,kind ON tenants FOR EACH ROW EXECUTE FUNCTION access_tenant_state_changed_fn();

CREATE FUNCTION access_domain_removed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
DELETE FROM access_roles WHERE scope='domain:'||OLD.id;
 UPDATE access_revisions SET revision=revision+1 WHERE scope='domain:'||OLD.id;
RETURN OLD;
END $trigger$;
CREATE TRIGGER access_domain_removed AFTER DELETE ON crm_data_domains FOR EACH ROW EXECUTE FUNCTION access_domain_removed_fn();

CREATE FUNCTION access_object_changed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1 WHERE scope=CASE WHEN NEW.tenant_id='domain:platform' THEN 'platform' WHEN NEW.tenant_id LIKE 'agency:%' THEN 'tenant:'||substr(NEW.tenant_id,8) ELSE NEW.tenant_id END;
RETURN NEW;
END $trigger$;
CREATE TRIGGER access_object_changed AFTER UPDATE OF config ON crm_objects FOR EACH ROW EXECUTE FUNCTION access_object_changed_fn();

CREATE FUNCTION access_object_removed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
UPDATE access_revisions SET revision=revision+1 WHERE scope=CASE WHEN OLD.tenant_id='domain:platform' THEN 'platform' WHEN OLD.tenant_id LIKE 'agency:%' THEN 'tenant:'||substr(OLD.tenant_id,8) ELSE OLD.tenant_id END;
RETURN OLD;
END $trigger$;
CREATE TRIGGER access_object_removed AFTER DELETE ON crm_objects FOR EACH ROW EXECUTE FUNCTION access_object_removed_fn();

CREATE FUNCTION crm_sync_insert_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_changes(tenant_id,object_name,id,data,version,created_at,updated_at,deleted_at,created_by) VALUES (NEW.tenant_id,NEW.object_name,NEW.id,NEW.data,NEW.version,NEW.created_at,NEW.updated_at,NEW.deleted_at,NEW.created_by) ON CONFLICT(tenant_id,object_name,id) DO UPDATE SET sequence=excluded.sequence,data=excluded.data,version=excluded.version,created_at=excluded.created_at,updated_at=excluded.updated_at,deleted_at=excluded.deleted_at,created_by=excluded.created_by;
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_sync_insert AFTER INSERT ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_sync_insert_fn();

CREATE FUNCTION crm_sync_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_changes(tenant_id,object_name,id,data,version,created_at,updated_at,deleted_at,created_by) VALUES (NEW.tenant_id,NEW.object_name,NEW.id,NEW.data,NEW.version,NEW.created_at,NEW.updated_at,NEW.deleted_at,NEW.created_by) ON CONFLICT(tenant_id,object_name,id) DO UPDATE SET sequence=excluded.sequence,data=excluded.data,version=excluded.version,created_at=excluded.created_at,updated_at=excluded.updated_at,deleted_at=excluded.deleted_at,created_by=excluded.created_by;
RETURN NEW;
END $trigger$;
CREATE TRIGGER crm_sync_update AFTER UPDATE ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_sync_update_fn();

CREATE FUNCTION crm_sync_delete_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
INSERT INTO crm_sync_changes(tenant_id,object_name,id,data,version,created_at,updated_at,deleted_at,created_by) VALUES (OLD.tenant_id,OLD.object_name,OLD.id,OLD.data,OLD.version+1,OLD.created_at,OLD.updated_at,COALESCE(OLD.deleted_at,to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),OLD.created_by) ON CONFLICT(tenant_id,object_name,id) DO UPDATE SET sequence=excluded.sequence,data=excluded.data,version=excluded.version,created_at=excluded.created_at,updated_at=excluded.updated_at,deleted_at=excluded.deleted_at,created_by=excluded.created_by;
RETURN OLD;
END $trigger$;
CREATE TRIGGER crm_sync_delete AFTER DELETE ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_sync_delete_fn();

CREATE FUNCTION access_tenant_removed_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $trigger$
BEGIN
IF OLD.id>0 THEN
DELETE FROM access_roles WHERE scope='tenant:'||OLD.id;
 UPDATE access_revisions SET revision=revision+1 WHERE scope='tenant:'||OLD.id;
END IF;
RETURN OLD;
END $trigger$;
CREATE TRIGGER access_tenant_removed AFTER DELETE ON tenants FOR EACH ROW EXECUTE FUNCTION access_tenant_removed_fn();

-- History field allowlist matches the final SQLite view, including all exclusions.
CREATE VIEW crm_record_history_fields AS
SELECT o.tenant_id, o.name AS object_name, f.key AS field_name,
 LEAST(365,GREATEST(1,CASE WHEN o.config::jsonb #>> '{studio,history,retentionDays}' IS NULL THEN 90 WHEN o.config::jsonb #> '{studio,history,retentionDays}'='true'::jsonb THEN 1 ELSE COALESCE(substring(o.config::jsonb #>> '{studio,history,retentionDays}' from '^[[:space:]]*([+-]?[0-9]+)'), '0')::numeric END))::integer AS retention_days
FROM crm_objects o
CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(o.config::jsonb -> 'fields')='object' THEN o.config::jsonb -> 'fields' ELSE '{}'::jsonb END) f
WHERE o.config::jsonb #> '{studio,history,enabled}' IN ('true'::jsonb,'1'::jsonb)
 AND o.config::jsonb #> '{studio,collection}' IS NULL
 AND COALESCE(o.config::jsonb #>> '{studio,business}','') NOT IN ('managed-customer','managed-agency')
 AND jsonb_typeof(o.config::jsonb #> '{studio,history,fields}')='array'
 AND f.key IN (SELECT value #>> '{}' FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.config::jsonb #> '{studio,history,fields}')='array' THEN o.config::jsonb #> '{studio,history,fields}' ELSE '[]'::jsonb END) WITH ORDINALITY AS chosen(value,ordinality) WHERE jsonb_typeof(value)='string' AND ordinality<=50)
 AND f.key !~ '[^A-Za-z0-9_]' AND left(f.key,1)<>'_'
 AND f.key NOT IN ('id','created_at','updated_at','deleted_at','created_by','updated_by','createdAt','updatedAt','deletedAt','createdBy','updatedBy','constructor','prototype')
 AND f.value ->> 'type' IN ('Textbox','Textarea','Email','Phone','Url','Address','Number','Currency','Dropdown','Autocomplete','Toggle','DateControl')
 AND COALESCE(f.value -> 'hidden','0'::jsonb) IN ('0'::jsonb,'false'::jsonb,'null'::jsonb)
 AND COALESCE(f.value -> 'readOnly','0'::jsonb) IN ('0'::jsonb,'false'::jsonb,'null'::jsonb)
 AND COALESCE(f.value #> '{config,sensitive}','0'::jsonb) IN ('0'::jsonb,'false'::jsonb,'null'::jsonb)
 AND COALESCE(f.value #> '{config,readable}','1'::jsonb) NOT IN ('0'::jsonb,'false'::jsonb)
 AND COALESCE(f.value -> 'readable','1'::jsonb) NOT IN ('0'::jsonb,'false'::jsonb)
 AND COALESCE(f.value #> '{config,multiple}','0'::jsonb) IN ('0'::jsonb,'false'::jsonb,'null'::jsonb)
 AND (f.value #> '{config,formula}' IS NULL OR f.value #> '{config,formula}'='null'::jsonb)
 AND (f.value #> '{config,relation}' IS NULL OR f.value #> '{config,relation}'='null'::jsonb)
 AND (f.value #> '{config,collectionRelation}' IS NULL OR f.value #> '{config,collectionRelation}'='null'::jsonb)
 AND (f.value #> '{config,collectionRelationTarget}' IS NULL OR f.value #> '{config,collectionRelationTarget}'='null'::jsonb);

CREATE FUNCTION savia_history_value(label text, value jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT CASE WHEN jsonb_typeof(value) IN ('string','number','boolean') THEN
 jsonb_build_object(label,CASE WHEN jsonb_typeof(value)='string' THEN to_jsonb(left(value #>> '{}',2048)) ELSE value END)
 || CASE WHEN jsonb_typeof(value)='string' AND length(value #>> '{}')>2048 THEN jsonb_build_object(label||'Truncated',true) ELSE '{}'::jsonb END
 ELSE '{}'::jsonb END
$$;
CREATE FUNCTION crm_history_write_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $$
DECLARE changes jsonb := '{}'::jsonb; f record; before_value jsonb; after_value jsonb;
 retention integer; changed boolean := false; action text; at_time timestamptz := clock_timestamp();
BEGIN
 FOR f IN SELECT * FROM crm_record_history_fields WHERE tenant_id=NEW.tenant_id AND object_name=NEW.object_name LOOP
  retention := f.retention_days;
  before_value := CASE WHEN TG_OP='UPDATE' THEN OLD.data::jsonb -> f.field_name ELSE NULL END;
  after_value := NEW.data::jsonb -> f.field_name;
  IF (TG_OP='INSERT' OR before_value IS DISTINCT FROM after_value)
    AND (jsonb_typeof(before_value) IN ('null','string','number','boolean') OR jsonb_typeof(after_value) IN ('null','string','number','boolean')) THEN
   changes := changes || jsonb_build_object(f.field_name, savia_history_value('before',before_value)||savia_history_value('after',after_value));
   changed := true;
  END IF;
 END LOOP;
 IF retention IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN action := 'created';
 ELSE
  IF NOT changed AND OLD.deleted_at IS NOT DISTINCT FROM NEW.deleted_at THEN RETURN NEW; END IF;
  action := CASE WHEN OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN 'deleted' WHEN OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN 'restored' ELSE 'updated' END;
 END IF;
 INSERT INTO crm_record_history(tenant_id,object_name,record_id,version,action,created_at,actor_kind,actor_id,cause_id,changes,expires_at)
 VALUES (NEW.tenant_id,NEW.object_name,NEW.id,NEW.version,action,to_char(at_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 COALESCE((SELECT actor_kind FROM crm_record_history_context WHERE tenant_id=NEW.tenant_id),'system'),
 (SELECT actor_id FROM crm_record_history_context WHERE tenant_id=NEW.tenant_id),
 (SELECT cause_id FROM crm_record_history_context WHERE tenant_id=NEW.tenant_id),changes::text,
 to_char((at_time + retention * interval '1 day') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 RETURN NEW;
END $$;
CREATE TRIGGER crm_history_insert AFTER INSERT ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_history_write_fn();
CREATE TRIGGER crm_history_update AFTER UPDATE ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_history_write_fn();
CREATE FUNCTION crm_history_delete_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $$
BEGIN DELETE FROM crm_record_history WHERE tenant_id=OLD.tenant_id AND object_name=OLD.object_name AND record_id=OLD.id; RETURN OLD; END $$;
CREATE TRIGGER crm_history_delete AFTER DELETE ON crm_records FOR EACH ROW EXECUTE FUNCTION crm_history_delete_fn();

CREATE FUNCTION workflow_record_write_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $$
DECLARE event_kind text := CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END;
BEGIN
 IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND (OLD.deleted_at IS NOT NULL OR NEW.data=OLD.data) THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM workflows w JOIN workflow_versions v ON v.workspace_id=w.workspace_id AND v.id=w.published_version
 WHERE w.workspace_id=NEW.tenant_id AND w.enabled=1 AND v.definition::jsonb #>> '{trigger,type}'=event_kind AND v.definition::jsonb #>> '{trigger,collection}'=NEW.object_name) THEN RETURN NEW; END IF;
 INSERT INTO workflow_events(workspace_id,collection,kind,before_state,after_state,depth,cause)
 SELECT NEW.tenant_id,NEW.object_name,event_kind,
 CASE WHEN TG_OP='INSERT' THEN '{}' ELSE (OLD.data::jsonb || jsonb_build_object('id',OLD.id,'_version',OLD.version,'created_at',OLD.created_at,'updated_at',OLD.updated_at))::text END,
 (NEW.data::jsonb || jsonb_build_object('id',NEW.id,'_version',NEW.version,'created_at',NEW.created_at,'updated_at',NEW.updated_at))::text,
 COALESCE(c.depth,0),c.cause FROM (SELECT 1) dummy LEFT JOIN workflow_write_context c ON c.workspace_id=NEW.tenant_id AND c.record_id=NEW.id;
 RETURN NEW;
END $$;
CREATE TRIGGER workflow_record_created AFTER INSERT ON crm_records FOR EACH ROW EXECUTE FUNCTION workflow_record_write_fn();
CREATE TRIGGER workflow_record_updated AFTER UPDATE OF data ON crm_records FOR EACH ROW EXECUTE FUNCTION workflow_record_write_fn();
-- SQLite json_extract returns integer 0/1 for booleans; workflow change detection
-- intentionally follows that scalar contract (distinct from history's typed diff).
CREATE FUNCTION savia_workflow_comparison(value jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT CASE WHEN value='true'::jsonb THEN '1'::jsonb WHEN value='false'::jsonb THEN '0'::jsonb ELSE NULLIF(value,'null'::jsonb) END
$$;
CREATE FUNCTION workflow_event_dispatch_fn() RETURNS trigger LANGUAGE plpgsql SET search_path = savia_core, pg_catalog AS $$
BEGIN
 IF NEW.depth<5 THEN
 INSERT INTO workflow_executions(workspace_id,id,workflow_id,version_id,owner_id,initiator_id,event_key,node_id,context,depth)
 SELECT w.workspace_id,v.id||':'||NEW.id,w.id,v.id,v.owner_id,v.owner_id,'event:'||NEW.id,v.definition::jsonb #>> '{nodes,0,id}',
 jsonb_build_object('trigger',NEW.after_state::jsonb,'before',NEW.before_state::jsonb,'steps','{}'::jsonb,
 'system',jsonb_build_object('owner',v.owner_id,'workspace',w.workspace_id,'event',NEW.id,'cause',NEW.cause))::text,NEW.depth
 FROM workflows w JOIN workflow_versions v ON v.workspace_id=w.workspace_id AND v.id=w.published_version
 WHERE w.workspace_id=NEW.workspace_id AND w.enabled=1 AND v.definition::jsonb #>> '{trigger,type}'=NEW.kind
 AND v.definition::jsonb #>> '{trigger,collection}'=NEW.collection AND (
 NEW.kind='created' OR COALESCE(jsonb_array_length(v.definition::jsonb #> '{trigger,changedFields}'),0)=0 OR EXISTS (
 SELECT 1 FROM jsonb_array_elements_text(v.definition::jsonb #> '{trigger,changedFields}') f(value)
 WHERE savia_workflow_comparison(NEW.before_state::jsonb -> f.value) IS DISTINCT FROM savia_workflow_comparison(NEW.after_state::jsonb -> f.value)));
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER workflow_event_dispatch AFTER INSERT ON workflow_events FOR EACH ROW EXECUTE FUNCTION workflow_event_dispatch_fn();
